  text-align: start;
}
.bcn-kb-hero__results[hidden] {
  display: none;
}
.bcn-kb-hero__result {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: var(--spacing-200) var(--spacing-300);
  border-radius: var(--radius-200);
  text-decoration: none;
  color: inherit;
}
.bcn-kb-hero__result[hidden] {
  display: none;
}
.bcn-kb-hero__result:hover,
.bcn-kb-hero__result.is-active {
  background: var(--color-surface-sunken);
}
.bcn-kb-hero__result-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--spacing-300);
}
.bcn-kb-hero__result-title {
  font-size: 0.9375rem;
  font-weight: var(--font-weight-medium);
  color: var(--color-text-primary);
  line-height: 1.35;
}
.bcn-kb-hero__result.is-active .bcn-kb-hero__result-title,
.bcn-kb-hero__result:hover .bcn-kb-hero__result-title {
  color: var(--color-text-link);
}
.bcn-kb-hero__result-cat {
  flex: none;
  font-size: 0.8125rem;
  color: var(--color-text-tertiary);
  white-space: nowrap;
}
.bcn-kb-hero__result-summary {
  font-size: 0.8125rem;
  color: var(--color-text-secondary);
  line-height: 1.4;
}
.bcn-kb-hero__result-title mark {
  background: color-mix(in srgb, var(--color-text-primary) 12%, transparent);
  color: inherit;
  border-radius: 2px;
  padding: 0 1px;
}
.bcn-kb-hero__no-results {
  margin: 0;
  padding: var(--spacing-300);
  font-size: 0.9375rem;
  color: var(--color-text-secondary);
}

.bcn-kbc {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-500);
}
.bcn-kbc__title {
  margin: 0;
  color: var(--color-text-primary);
}
.bcn-kbc__grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-400);
}
.bcn-kbc__grid {
  grid-template-columns: repeat(2, 1fr);
}
.bcn-kbc__grid {
  grid-template-columns: repeat(3, 1fr);
}
.bcn-kbc__card {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-300);
  padding: var(--spacing-500);
  background: var(--color-surface);
  border: 1px solid var(--color-border);
