  color: var(--color-text-primary);
}
.bcn-kbc__card-desc {
  margin: 0;
  font-size: 0.9375rem;
  line-height: 1.5;
  color: var(--color-text-secondary);
}
.bcn-kbc__featured {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-150);
}
.bcn-kbc__featured-link {
  font-size: 0.9375rem;
  font-weight: var(--font-weight-medium);
  line-height: 1.35;
  color: var(--color-text-primary);
  text-decoration: none;
  transition: color 0.12s ease;
}
.bcn-kbc__foot {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--spacing-300);
  margin-top: auto;
  padding-top: var(--spacing-300);
  border-top: 1px solid var(--color-border-light);
}
.bcn-kbc__count {
  font-size: 0.8125rem;
  color: var(--color-text-tertiary);
  white-space: nowrap;
}
.bcn-kbc__viewall {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-100);
  font-size: 0.9375rem;
  font-weight: var(--font-weight-semibold);
